import unittest

from solution import combine_theme


class CombineThemeTests(unittest.TestCase):
    def test_combines_without_mutating_inputs_and_preserves_order(self):
        base = {"color": "blue", "font": "serif", "spacing": 4}
        overrides = {"font": "sans", "border": "thin", "color": "red"}
        base_before = base.copy()
        overrides_before = overrides.copy()
        result = combine_theme(base, overrides)
        self.assertEqual(result, {"color": "red", "font": "sans", "spacing": 4, "border": "thin"})
        self.assertEqual(list(result), ["color", "font", "spacing", "border"])
        self.assertEqual(base, base_before)
        self.assertEqual(overrides, overrides_before)
        self.assertIsNot(result, base)
        self.assertIsNot(result, overrides)

    def test_deep_copies_values_from_both_inputs(self):
        base_only = {"layers": [{"name": "base"}]}
        overridden_in_base = {"old": [1]}
        override_value = {"new": [{"x": 2}]}
        base = {"kept": base_only, "changed": overridden_in_base}
        overrides = {"changed": override_value}
        result = combine_theme(base, overrides)

        self.assertEqual(result, {"kept": base_only, "changed": override_value})
        self.assertIsNot(result["kept"], base_only)
        self.assertIsNot(result["kept"]["layers"], base_only["layers"])
        self.assertIsNot(result["changed"], override_value)
        self.assertIsNot(result["changed"]["new"], override_value["new"])

        base_only["layers"][0]["name"] = "mutated"
        override_value["new"][0]["x"] = 99
        self.assertEqual(result["kept"], {"layers": [{"name": "base"}]})
        self.assertEqual(result["changed"], {"new": [{"x": 2}]})

    def test_empty_inputs(self):
        result = combine_theme({}, {})
        self.assertEqual(result, {})
        self.assertIsInstance(result, dict)

    def test_empty_overrides_still_returns_deep_copy(self):
        nested = {"items": [1]}
        base = {"nested": nested}
        result = combine_theme(base, {})
        self.assertEqual(result, base)
        self.assertIsNot(result, base)
        self.assertIsNot(result["nested"], nested)
        self.assertIsNot(result["nested"]["items"], nested["items"])

    def test_non_dictionaries_raise_type_error_without_mutation(self):
        base = {"x": [1]}
        overrides = {"y": [2]}
        cases = [(None, overrides), ([], overrides), (base, None), (base, [])]
        for left, right in cases:
            with self.subTest(left=left, right=right):
                base_before = {"x": [1]}
                overrides_before = {"y": [2]}
                with self.assertRaises(TypeError):
                    combine_theme(left, right)
                self.assertEqual(base, base_before)
                self.assertEqual(overrides, overrides_before)


if __name__ == "__main__":
    unittest.main()

